// ratelimit/ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time so tests can advance deterministically.
type Clock interface {
	Now() time.Time
}

// RealClock returns the system time.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Bucket is a concurrency-safe token-bucket rate limiter.
//
// The bucket holds at most capacity tokens. It is refilled at rate
// tokens per second, up to capacity. AllowN consumes n tokens if
// available; otherwise it returns false without consuming.
type Bucket struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
}

// NewBucket validates and returns a Bucket pre-filled with capacity tokens.
//
// rate must be > 0 and capacity must be > 0. last is the refill reference
// time; if zero, time.Now() is used.
func NewBucket(clock Clock, rate, capacity float64, last time.Time) (*Bucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if last.IsZero() {
		last = clock.Now()
	}
	return &Bucket{
		clock:    clock,
		rate:     rate,
		capacity: capacity,
		tokens:   capacity,
		last:     last,
	}, nil
}

// AllowN reports whether n tokens can be consumed now. On success it
// atomically consumes n tokens; otherwise no tokens are consumed.
//
// n must be > 0; non-positive values are rejected.
func (b *Bucket) AllowN(n int) (bool, error) {
	if n <= 0 {
		return false, errors.New("ratelimit: n must be positive")
	}
	b.mu.Lock()
	defer b.mu.Unlock()

	now := b.clock.Now()
	b.tokens = b.refillLocked(now)
	if float64(n) <= b.tokens {
		b.tokens -= float64(n)
		return true, nil
	}
	return false, nil
}

// Tokens returns the current token count (for observability/tests).
func (b *Bucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.refillLocked(b.clock.Now())
}

// refillLocked advances tokens from b.last to now, capped at capacity.
// Callers must hold b.mu.
func (b *Bucket) refillLocked(now time.Time) float64 {
	elapsed := now.Sub(b.last).Seconds()
	if elapsed > 0 {
		b.tokens += elapsed * b.rate
		if b.tokens > b.capacity {
			b.tokens = b.capacity
		}
		b.last = now
	}
	return b.tokens
}
