// ratelimit/ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can advance deterministically.
type Clock interface {
	Now() time.Time
}

// RealClock returns the system time.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Bucket is a concurrency-safe token-bucket rate limiter.
type Bucket struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
}

// NewBucket validates and returns a Bucket.
func NewBucket(clock Clock, capacity, rate float64) (*Bucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if math.IsNaN(capacity) || math.IsInf(capacity, 0) || capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be a finite positive number")
	}
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be a finite positive number")
	}
	now := clock.Now()
	return &Bucket{
		clock:    clock,
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     now,
	}, nil
}

// AllowN reports whether n tokens can be consumed without blocking.
// It never blocks; on success it deducts n tokens.
func (b *Bucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()

	now := b.clock.Now()
	elapsed := now.Sub(b.last)
	if elapsed > 0 {
		b.tokens += float64(elapsed.Nanoseconds()) * (b.rate / 1e9)
		if b.tokens > b.capacity {
			b.tokens = b.capacity
		}
		b.last = now
	}

	fn := float64(n)
	if b.tokens < fn {
		return false
	}
	b.tokens -= fn
	return true
}

// Tokens returns the current token count (for observability/tests).
func (b *Bucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()

	now := b.clock.Now()
	elapsed := now.Sub(b.last)
	if elapsed > 0 {
		t := b.tokens + float64(elapsed.Nanoseconds())*(b.rate/1e9)
		if t > b.capacity {
			t = b.capacity
		}
		return t
	}
	return b.tokens
}
